{
  "queries": [
    {
      "doc_id": "ECN-2026-049",
      "query": "Please provide the approval trail and sign-off dates for ECN-2026-049. Also include any test reports or validation evidence used to justify the change to Heat Treat hydraulic forging press #3."
    },
    {
      "doc_id": "QS-PROC-10",
      "query": "I need the latest revision of QS-PROC-10 and records demonstrating compliance with the specified machining surface finish (P2) limits over the past six months. If there were any deviations, summarize corrective actions."
    },
    {
      "doc_id": "SOP-P1-L4-01",
      "query": "For SOP-P1-L4-01, please list required pre-start checks that require engineering approval and identify any recent revisions—include change justification and evidence of operator training on the updated startup procedure."
    },
    {
      "doc_id": "SOP-P3-L3-04",
      "query": "Requesting the shift handover checklist used on the Machining line per SOP-P3-L3-04 and samples of completed handover records for the last week. Highlight any outstanding open actions from those handovers."
    },
    {
      "doc_id": "QS-CFW-1730-97",
      "query": "Provide the acceptance criteria and inspection method references in QS-CFW-1730-97 for valve body F316. Also attach recent inspection reports showing conformance or nonconformance."
    },
    {
      "doc_id": "SOP-P2-L2-04",
      "query": "For the Ring Rolling line shift handover SOP-P2-L2-04, confirm who is authorized to sign handovers and supply examples of signatures from last month's handovers for audit traceability."
    },
    {
      "doc_id": "SOP-P1-L4-05",
      "query": "Please supply the planned shutdown procedure SOP-P1-L4-05 and provide evidence of the most recent planned shutdown execution, including the pre-shutdown risk assessment and post-shutdown inspection checklist."
    },
    {
      "doc_id": "SOP-P1-L1-02",
      "query": "I need the product changeover procedure for the Hot Forge line (SOP-P1-L1-02) and records showing that the last changeover followed the SOP, including checklist completion and final verification sign-off."
    },
    {
      "doc_id": "SOP-P1-L1-03",
      "query": "For SOP-P1-L1-03 First-article inspection on the Hot Forge line, provide the first-article report template and the most recent completed first-article inspection for a production change, with noted dispositions."
    },
    {
      "doc_id": "SOP-P1-L4-03",
      "query": "Request the procedure SOP-P1-L4-03 and the documentation for the last first-article inspection performed on the Heat Treat line, including measurement data and approver signature(s)."
    },
    {
      "doc_id": "SOP-P3-L3-05",
      "query": "Please produce the Planned shutdown procedure for the Machining line (SOP-P3-L3-05) and any post-shutdown corrective action reports generated after the last execution."
    },
    {
      "doc_id": "QS-CFW-6417-61",
      "query": "Provide the quality specification QS-CFW-6417-61 for bearing ring (52100) and any sampling plans tied to it. Include records of recent nonconformances and how they were dispositioned."
    },
    {
      "doc_id": "SOP-P2-L1-01",
      "query": "For SOP-P2-L1-01 Line startup - Hot Forge line, identify required environmental and equipment verifications and submit evidence that the most recent startup met those requirements."
    },
    {
      "doc_id": "ECN-2026-007",
      "query": "Share the change justification, risk assessment, and validation evidence for ECN-2026-007 affecting Heat Treat hydraulic forging press #2, plus the list of personnel who approved the change."
    },
    {
      "doc_id": "QS-CFW-7189-64",
      "query": "I need to review QS-CFW-7189-64 for bearing ring (52100). Please include acceptance criteria, inspection frequencies, and any deviations recorded in the last audit cycle."
    },
    {
      "doc_id": "QS-CFW-6160-72",
      "query": "Provide the quality spec QS-CFW-6160-72 for crankshaft blank (4340). Also supply evidence of heat treatment and hardness verification for the last batch produced under this spec."
    },
    {
      "doc_id": "ECN-2026-023",
      "query": "For ECN-2026-023 (Hot Forge radial ring rolling mill #1), supply the list of affected documents, implementation plan, and post-implementation monitoring results or field performance data."
    },
    {
      "doc_id": "QS-CFW-3043-62",
      "query": "Request the quality specification QS-CFW-3043-62 for flange blank (4140), including dimensional tolerances and non-destructive testing requirements, plus recent inspection evidence."
    },
    {
      "doc_id": "SOP-P1-L1-04",
      "query": "Please provide the Hot Forge line shift handover SOP-P1-L1-04 and samples of completed shift handover logs for the last three shifts, noting any incomplete items or pending actions."
    },
    {
      "doc_id": "ECN-2026-017",
      "query": "For ECN-2026-017 (Ring Rolling heat treat furnace #3), please provide the change record, validation test results, and any updated maintenance schedules resulting from the change."
    }
  ]
}
